            }

            h4 {
                font-size: 9pt;
                font-weight: 500;
            }

            .item .name {
                font-weight: bold;
            }

            .item .description {
                font-size: 9pt;
                font-weight: 300;
            }

            .item {
                font-size: 9pt;
            }

            .item {
                margin-bottom: 10px;
            }

            .item span:first-child {
                font-weight: bold;
            }

            .price {
                float: right;
            }

            p {
                padding: 0;
                margin: 0;
                font-weight: 300;
                font-size: 9pt;
                width: 70%;
            }

            .page {
                width: 210mm;
                height: 297mm;
                margin: 0 auto;
                box-sizing: border-box;
                page-break-after: initial;
                position: relative;
                overflow: hidden;
                background-color: white;
                font-family: Jungka, serif;
                padding-left: 20mm;
                padding-right: 20mm;
                padding-top: 10mm;
            }

            .page .footer {
                position: absolute;
                bottom: 0;
                padding-left: 20mm;
                padding-right: 20mm;
                left: 0;
                right: 0;
                z-index: 10;
                font-size: 9pt;
                font-weight: 300;
                overflow: hidden;
                height: 100%;
            }

            .page .footer .left {
                width: 50%;
                float: left;
                font-weight: 500;
            }

            .page .footer .left .content {
                width: 100px:
            }

            .page .footer .right {
                width: 50%;
                float: right;
            }

            .page .footer .right .origin {
                font-weight: 500;
            }

            .page .footer .badge {
                position: absolute;
                bottom: 20px;
                height: 51mm;
                z-index: 10;
                left: 0;
                right: 0;
            }

            .page .footer .illustration {
            }

            .columns {
                position: absolute;
                width: 630px;
                bottom: 20mm;
                display: grid;
                grid-template-columns: 1fr 1fr;
                justify-content: left;
                z-index: 10;
            }

            .columns h4 {
                margin-bottom: 5px;
                margin-top: 0;
            }

            .columns .left .content {
                font-size: 10pt;
            }

            .columns .origin {
                display: grid;
                grid-template-columns: 1fr 1fr;
                margin-top: 3px;
                font-size: 10pt;
            }

            #overlay {
                position: absolute;
                right: 60px;
                top: 40px;
                height: 24mm;
                width: 32mm;
                rotate: 45deg;
